#Region @DOC
#### Description:
#This process copies data from a source into a target cube. It is designed for use in production environments where data needs to be moved, transformed, or archived between cubes — even when those cubes have different structures, dimension counts, or dimension orderings. Common uses include populating a reporting cube from a planning cube, and archiving data from one cube to another.
#
#### How to Use:
#`pDatasource` defines the source of data to load from. It can be passed as either a plain string or a JSON Object.
#
#If passed as a plain string, the process will check whether a cube with that name exists. If it does, it will be used as a cube view datasource. If it does not, it will be assumed to be a CSV file path.
#
#To be more explicit, pass a JSON Object with datasource properties as keys:
#```json
#{
#  "datasourcenameforserver": "Sales Cube",
#  "datasourcecubeview": "My View"
#}
#```
#
#`pTargetCube` is the name of the cube to write data into.
#
#The process automatically maps dimensions that exist in both the source and target cube by name, regardless of their index position in each cube. For dimensions in the source that do not exist in the target, their values will be accumulated (all N-level elements summed) unless constrained by `pFilter`.
#
#`pDimMap` is required when the target cube contains dimensions that do not appear in the source cube. It assigns a fixed element for each such dimension. It must be either a JSON Object or JSON Array.
#
#If `pDimMap` is a JSON Object, the keys are the dimension names and the values are the elements to use:
#```json
#{
#  "Account": "9999",
#  "Scenario": "Actual"
#}
#```
#If `pDimMap` is a JSON Array, the index of each item corresponds to the index of the dimension in the target cube:
#```json
#[null, null, "9999", null, "Actual"]
#```
#
#> [!NOTE]
#> Elements specified in `pDimMap` must be N-level elements unless `pSuppressConsol` is set to `0`.
#>
#> If a dimension in `pDimMap` is given more than one element, the process will execute recursively — once per element — accumulating results.
#
#`pFilter` defines which elements from the source cube to include in the load. It is interpreted in the same way as in other Bedrock processes — as either a JSON Object (dimension name → element or array of elements) or a JSON Array (index-aligned to source cube dimensions). Elements can be element names, subset names, MDX expressions, or a JSON Array of any mix of the three.
#
#For example, to copy only Actual data for 2023 from a Sales cube into a General Ledger cube, writing to Account `9999`:
#```json
#{
#  "pDatasource": "Sales Cube",
#  "pTargetCube": "General Ledger",
#  "pFilter":     {"Year": "2023", "Version": "Actual"},
#  "pDimMap":     {"Account": "9999"},
#  "pZeroTarget": 1
#}
#```
#
#To parallelise the same load across the Region dimension using 4 threads:
#```json
#{
#  "pDatasource":            "Sales Cube",
#  "pTargetCube":            "General Ledger",
#  "pFilter":                {"Year": "2023", "Version": "Actual"},
#  "pDimMap":                {"Account": "9999"},
#  "pMultithreadDimensions": ["Region"],
#  "pMaxThreads":            4
#}
#```
#
#> [!NOTE]
#> Any dimension listed in `pMultithreadDimensions` must not also appear in `pFilter`. The process uses that dimension as a parallelisation slicer, splitting it into individual recursive calls — one per element.
#
#When `pZeroTarget` is `1` (the default), the target cube is cleared before loading begins. The scope of the clear is determined by the intersection of `pFilter` and `pDimMap` values for dimensions that exist in the target. Set `pZeroTarget` to `0` to add source values on top of existing target values instead.
#
#`pFactor` and `pIncrement` allow values to be transformed during the copy. `pFactor` multiplies every source value before it is written. `pIncrement`, when set to `1`, adds the source value to the existing target cell value rather than replacing it. These only apply to numeric cells — string cells are passed through as-is.
#
#- `pDatasource` - Source cube name, CSV file path, or JSON Object with full datasource specification.
#- `pTargetCube` - Name of the cube to write data into.
#- `pFilter` - JSON Object or Array specifying which source elements to include. See above.
#- `pExcept` - Interpreted the same way as `pFilter`, but any element specified here will be excluded from the source view.
#- `pDimMap` - JSON Object or Array mapping target-only dimensions to fixed element values. Required when the target has dimensions not present in the source.
#- `pMultithreadDimensions` - JSON Array of dimension names to parallelise execution across. Each element in the dimension becomes a separate recursive call. Must not overlap with `pFilter`.
#- `pMaxThreads` - Maximum number of concurrent threads when `pMultithreadDimensions` is in use. Default = `1`.
#- `pZeroTarget` - Clear the target before loading (`1` = yes, `0` = no). Default = `1`.
#- `pFactor` - Multiply all source values by this number before writing. Default = `1`.
#- `pIncrement` - If `1`, add source values to existing target values rather than replacing them. Default = `0`.
#- `pSuppressConsol` - Skip consolidated source elements (`1` = yes). Default = `1`.
#- `pSuppressConsolStrings` - Skip consolidated string cells (`1` = yes). Default = `1`.
#- `pSuppressRules` - Suppress rule-derived values in the source view (`1` = yes). Default = `1`.
#- `pSuppressZero` - Skip zero-value source cells (`1` = yes). Default = `1`.
#- `pMappingOverride` - Directly override the internal dimension index mapping array. Replaces the auto-generated mapping entirely. Use with caution.
#- `pSandbox` - Name of a sandbox to direct writes into. The sandbox must exist and be valid for the current user.
#- `pTemp` - Whether to delete temporary views and subsets after execution. `0` = keep all, `1` = delete all, `2` = keep subsets only. Default = `1`.
#- `pUseFile` - Copy via an intermediate file export/import to reduce cube locking. `0` = no file, `1` = use file and delete it, `2` = use file and retain it. Default = `0`.
#- `pDecimalSeparator` - Decimal separator used for string-to-number conversion. Default = `.`.
#- `pThousandSeparator` - Thousand separator used for string-to-number conversion. Default = `,`.
#- `pLogOutput` - Write parameters and action summary to the server message log (`0` = off, `1` = on). Default = `0`.
#- `pStrictErrorHandling` - If `1`, exit with major error status via `ProcessQuit` on any error. Default = `0`.
#- `pJson` - JSON Object to pass all parameters at once. Overrides individually passed parameters for any keys included.
#EndRegion @DOC

### Global Variables
StringGlobalVariable('sProcessReturnCode');
NumericGlobalVariable('nProcessReturnCode');


### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = JsonAdd( '{"Info": [], "Error": []}', '/Info/0', StringToJson( 'Process: '''|cThisProcName|''' run by User: '''|cUsername|'''.' ) );

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pDatasource":            null,
  "pDecimalSeparator":      ".",
  "pDimMap":                "",
  "pExcept":                "",
  "pFilter":                "",
  "pMappingOverride":       "",
  "pMultithreadDimensions": "",
  "pSandbox":               "",
  "pTargetCube":            null,
  "pThousandSeparator":     ",",
  "pFactor":                1,
  "pIncrement":             0,
  "pLogOutput":             0,
  "pMaxThreads":            0,
  "pStrictErrorHandling":   0,
  "pSuppressConsol":        1,
  "pSuppressConsolStrings": 1,
  "pSuppressRules":         1,
  "pSuppressZero":          1,
  "pTemp":                  1,
  "pZeroTarget":            1
}';

pPassedParameters = '{
  "pDatasource":            '|StringToJson  ( pDatasource            )|',
  "pDecimalSeparator":      '|StringToJson  ( pDecimalSeparator      )|',
  "pFilter":                '|StringToJson  ( pFilter                )|',
  "pDimMap":                '|StringToJson  ( pDimMap                )|',
  "pExcept":                '|StringToJson  ( pExcept                )|',
  "pMappingOverride":       '|StringToJson  ( pMappingOverride       )|',
  "pMultithreadDimensions": '|StringToJson  ( pMultithreadDimensions )|',
  "pSandbox":               '|StringToJson  ( pSandbox               )|',
  "pTargetCube":            '|StringToJson  ( pTargetCube            )|',
  "pThousandSeparator":     '|StringToJson  ( pThousandSeparator     )|',
  "pFactor":                '|NumberToString( pFactor                )|',
  "pIncrement":             '|NumberToString( pIncrement             )|',
  "pLogOutput":             '|NumberToString( pLogOutput             )|',
  "pMaxThreads":            '|NumberToString( pMaxThreads        )|',
  "pStrictErrorHandling":   '|NumberToString( pStrictErrorHandling   )|',
  "pSuppressConsol":        '|NumberToString( pSuppressConsol        )|',
  "pSuppressConsolStrings": '|NumberToString( pSuppressConsolStrings )|',
  "pSuppressRules":         '|NumberToString( pSuppressRules         )|',
  "pSuppressZero":          '|NumberToString( pSuppressZero          )|',
  "pTemp":                  '|NumberToString( pTemp                  )|',
  "pZeroTarget":            '|NumberToString( pZeroTarget            )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pDatasource            =                 JsonToString( pJson, '/pDatasource'            );
pDecimalSeparator      =                 JsonToString( pJson, '/pDecimalSeparator'      );
pDimMap                =                 JsonToString( pJson, '/pDimMap'                );
pExcept                =                 JsonToString( pJson, '/pExcept'                );
pFilter                =                 JsonToString( pJson, '/pFilter'                );
pMappingOverride       =                 JsonToString( pJson, '/pMappingOverride'       );
pMultithreadDimensions =                 JsonToString( pJson, '/pMultithreadDimensions' );
pSandbox               =                 JsonToString( pJson, '/pSandbox'               );
pTargetCube            =                 JsonToString( pJson, '/pTargetCube'            );
pThousandSeparator     =                 JsonToString( pJson, '/pThousandSeparator'     );
# Numeric Parameters
pFactor                = StringToNumber( JsonToString( pJson, '/pFactor'                ) );
pIncrement             = StringToNumber( JsonToString( pJson, '/pIncrement'             ) );
pLogOutput             = StringToNumber( JsonToString( pJson, '/pLogOutput'             ) );
pMaxThreads            = StringToNumber( JsonToString( pJson, '/pMaxThreads'        ) );
pStrictErrorHandling   = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling'   ) );
pSuppressConsol        = StringToNumber( JsonToString( pJson, '/pSuppressConsol'        ) );
pSuppressConsolStrings = StringToNumber( JsonToString( pJson, '/pSuppressConsolStrings' ) );
pSuppressRules         = StringToNumber( JsonToString( pJson, '/pSuppressRules'         ) );
pSuppressZero          = StringToNumber( JsonToString( pJson, '/pSuppressZero'          ) );
pTemp                  = StringToNumber( JsonToString( pJson, '/pTemp'                  ) );
pZeroTarget            = StringToNumber( JsonToString( pJson, '/pZeroTarget'            ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  sVal = JsonGet( pJson, sKey );
  sValType = JsonType( JsonToString( sVal ) );
  
  IF( sValType @= 'object' % sValType @= 'array' );
    sVal = JsonToString( sVal );
    pJson = JsonReplace( pJson, sKey, sVal );
  ENDIF;
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

################################################################################################# 
#Region - Validate Parameters

nErrors = 0;
sTargetCube = pTargetCube;

nFactor            = IF( pFactor            = 0, 1, pFactor );
pDecimalSeparator  = IF( pDecimalSeparator  @= '', '.', pDecimalSeparator  );
pThousandSeparator = IF( pThousandSeparator @= '', ',', pThousandSeparator );

# If specified source cube doesn't exist then terminate process
#If( CubeExists(   pSrcCube   ) = 0 );
#    nErrors = nErrors + 1;
#  sMessage = Expand( 'Invalid source cube specified: %pSrcCube%.');
#  LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
#EndIf;

# If specified target cube doesn't exist then terminate process
#If( CubeExists(   pTgtCube   ) = 0 );
#  nErrors = nErrors + 1;
#  sMessage = Expand( 'Invalid target cube specified: %pTgtCube%.');
#  LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
#EndIf;

# Validate Sandbox
If( TRIM( pSandbox ) @<> '' );
    If( ServerSandboxExists( pSandbox ) = 0 );
        SetUseActiveSandboxProperty( 0 );
        nErrors = nErrors + 1;
        sMessage = Expand('Sandbox %pSandbox% is invalid for the current user.');
#        LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
    Else;
        ServerActiveSandboxSet( pSandbox );
        SetUseActiveSandboxProperty( 1 );
    EndIf;
Else;
    SetUseActiveSandboxProperty( 0 );
EndIf;

# Convert pDatasource to JSON Object if not already
sDatasourceJsonType = JsonType( pDatasource );
IF( sDatasourceJsonType @<> 'object' );
  sDatasourceName = pDatasource;
  pDatasource = '{"Name":'|StringToJson( sDatasourceName )|'}';
ENDIF;

# LOWER all keys
nCount = JsonSize( pDatasource );
WHILE( nCount > 0 );
  nCount = nCount - 1;
  
  sKey = JsonGetKey( pDatasource, 0 );
  pDatasource = JsonMove( pDatasource, sKey, LOWER( sKey ) );
END;

# Validate pFilter, pExcept, and pDimMap
IF( pFilter @= '' ); pFilter = '{}'; ENDIF;
IF( pExcept @= '' ); pExcept = '{}'; ENDIF;
IF( pDimMap @= '' ); pDimMap = '{}'; ENDIF;

pFilterType = JsonType( pFilter );
pExceptType = JsonType( pExcept );
pDimMapType = JsonType( pDimMap );

IF( pFilterType @<> 'array' & pFilterType @<> 'object' );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Error: pFilter has invalid type "'|pFilterType|'".' ) );
ENDIF;

IF( pExceptType @<> 'array' & pExceptType @<> 'object' );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Error: pExcept has invalid type "'|pExceptType|'".' ) );
ENDIF;

IF( pDimMapType @<> 'array' & pDimMapType @<> 'object' );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Error: pDimMap has invalid type "'|pDimMapType|'".' ) );
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

################################################################################################# 
#Region - Define Datasource

# DatasourceName
sName                    = JsonToString( pDatasource, '/name' );
sDatasourceName          = JsonToString( pDatasource, '/datasourcename' );
sDatasourceNameForServer = JsonToString( pDatasource, '/datasourcenameforserver' );
sDatasourceNameForClient = JsonToString( pDatasource, '/datasourcenameforclient' );
sDatasourceName          = IF( sDatasourceName @= '', sName, sDatasourceName );
sDatasourceNameForServer = IF( sDatasourceNameForServer @= '', sDatasourceName, sDatasourceNameForServer );
sDatasourceNameForClient = IF( sDatasourceNameForClient @= '', sDatasourceNameForServer, sDatasourceNameForClient );
DatasourceNameforServer = sDatasourceNameForServer;
DatasourceNameForClient = sDatasourceNameForClient;

DatasourceType = UPPER( JsonToString( pDatasource, '/datasourcetype' ) );
# If DatasourceType is not specified, try to infer from sName, based on if a cube exists  
IF( DatasourceType @= '' );
  DatasourceType = IF( CubeExists( sDatasourceNameForServer ) = 1, 'VIEW', 'CHARACTERDELIMITED' );
ENDIF;

## Get Datasource Info from pDatasource
# File Datasources
sDatasourceASCIIDelimiter = JsonToString( pDatasource, '/datasourceasciidelimiter' );
sDatasourceASCIIQuoteCharacter = JsonToString( pDatasource, '/datasourceasciiquotecharacter' );
sDatasourceASCIIDecimalSeparator = JsonToString( pDatasource, '/datasourceasciidecimalseparator' );
sDatasourceASCIIThousandSeparator = JsonToString( pDatasource, '/datasourceasciithousandseparator' );
nDatasourceASCIIHeaderRecords = StringToNumberEx( JsonToString( pDatasource, '/datasourceasciiheaderrecords' ), pDecimalSeparator, pThousandSeparator );

# TM1 Datasources
sDatasourceCubeView = JsonToString( pDatasource, '/datasourcecubeview' );
sDatasourceDimensionSubset = JsonToString( pDatasource, '/datasourcedimensionsubset' );

# ODBC/OLEDBOLAP Datasources
sDatasourcePassword = JsonToString( pDatasource, '/datasourcepassword' );
sDatasourceQuery = JsonToString( pDatasource, '/datasourcequery' );
sDatasourceUsername = JsonToString( pDatasource, '/datasourceusername' );

# JSON Datasources
sDatasourceJsonRootPointer = JsonToString( pDatasource, '/datasourcejsonrootpointer' );
sDatasourceJsonVariableMapping = JsonToString( pDatasource, '/datasourcejsonvariablemapping' );

## Define Datasource based on info
# File Datasources
DatasourceASCIIDelimiter = IF( sDatasourceASCIIDelimiter @= '', ',', sDatasourceASCIIDelimiter );
DatasourceASCIIQuoteCharacter = IF( sDatasourceASCIIQuoteCharacter @= '', '"', sDatasourceASCIIQuoteCharacter );
DatasourceASCIIDecimalSeparator = IF( sDatasourceASCIIDecimalSeparator @= '', pDecimalSeparator, sDatasourceASCIIDecimalSeparator );
DatasourceASCIIThousandSeparator = IF( sDatasourceASCIIThousandSeparator @= '', pThousandSeparator, sDatasourceASCIIThousandSeparator );
  
# TM1 Datasources
DatasourceCubeView = sDatasourceCubeView;
DatasourceDimensionSubset = sDatasourceDimensionSubset;
  
# ODBC/OLEDBOLAP Datasources
DatasourcePassword = sDatasourcePassword;
DatasourceQuery = sDatasourceQuery;
DatasourceUsername = sDatasourceUsername;
  
# JSON Datasources
DatasourceJsonRootPointer = IF( sDatasourceJsonRootPointer @= '', '/', sDatasourceJsonRootPointer );
DatasourceJsonVariableMapping = IF( sDatasourceJsonVariableMapping @= '', '{}', sDatasourceJsonVariableMapping );

#EndRegion - Define Datasource
#################################################################################################

# Create default mapping for pTargetCube
sMapping = '[]';
nTargetDimensionCount = CubeDimensionCountGet( pTargetCube );
sTargetMeasureDimension = TABDIM( pTargetCube, nTargetDimensionCount );
i = 0;
WHILE( i < nTargetDimensionCount );
  sMapping = JsonAdd( sMapping, '', NumberToString( i ) );
  i = i + 1;
END;

# Create a generic sMapping, where all of the Source Dimensions are mapped to the correct Target Dimensions. sMapping will be modified according to passed parameters later on.
IF( DataSourceType @<> 'VIEW' );
  sSourceCube = sTargetCube;
ELSE;
  sSourceCube = DatasourceNameForServer;
ENDIF;

nSourceDimensionCount = CubeDimensionCountGet( sSourceCube );
sMapping = JsonAdd( sMapping, '', NumberToString( nSourceDimensionCount ) );
WHILE( nSourceDimensionCount > 0 );
  sSourceDimension = TABDIM( sSourceCube, nSourceDimensionCount );
  nTargetCount = nTargetDimensionCount;
  WHILE( nTargetCount > 0 );
    sTargetDimension = TABDIM( sTargetCube, nTargetCount );
    IF( sSourceDimension @= sTargetDimension );
      sMapping = JsonReplace( sMapping, nTargetCount-1, NumberToString( nSourceDimensionCount-1 ) );
    ENDIF;
    
    nTargetCount = nTargetCount - 1;
  END;
  nSourceDimensionCount = nSourceDimensionCount - 1;
END;
  
################################################################################################# 
#Region - Interpret parameters based on datasource type

IF( DatasourceType @= 'CHARACTERDELIMITED' );
    
ELSEIF( DatasourceType @= 'VIEW' );
  IF( DatasourceCubeView @= '' );
    ExecuteProcess('}bedrock.cube.view.create.from_json',
      'pCube', sSourceCube,
      'pView', cTemp,
      'pFilter', pFilter,
      'pExcept', pExcept,
      'pJson', pJson );
    DatasourceCubeView = cTemp;
  ENDIF;
  
  #################################################################################################
  #Region - Interpret pDimMap, pElementMapping, and Multi-Threading Parameters
  
  # REQUIREMENTS:
  # - Convert pFilter to Dimension Object instead of Array, with values as arrays
  # - Convert pExcept to Dimension Object instead of Array, with values as arrays
  # - Have pDimMap be Object with keys as Dimension and values as arrays
  
  # Convert Filters (pFilter, pExcept, pDimMap) to standardized form
  pFilters = '{"pFilter":'|pFilter|',"pExcept":'|pExcept|',"pDimMap":'|pDimMap|'}';
  sFilters = '{"pFilter":{},"pExcept":{},"pDimMap":{}}';
  # Loop through pFilter, pExcept, and pDimMap
  nKey = JsonSize( sFilters ); WHILE( nKey > 0 ); nKey = nKey - 1;
    sKey = JsonGetKey( sFilters, nKey );
    
    sCube = IF( sKey @= 'pDimMap', sTargetCube, sSourceCube );
    nCube = CubeDimensionCountGet( sCube );
    
    # Loop Through Dimensions
    i = 0; WHILE( i < nCube ); i = i + 1;
      sDimension = TABDIM( sCube, i );
      sI = NumberToString( i-1 );
      
      sVal = JsonGet( pFilters, '/'|sKey|'/'|IF( JsonType( pFilters, '/'|sKey ) @= 'array', sI, sDimension ) );
      IF( JsonType( sVal ) @= 'string' ); 
        sVal = '['|sVal|']';
      ELSEIF( JsonType( sVal ) @<> 'array' );
        sVal = '[]';
      ENDIF;
      sFilters = JsonAdd( sFilters, '/'|sKey|'/'|sDimension, sVal );
      
    END;
  END;

  # Recursive Calls for multiple elements in pDimMap
  sFiltersList = '['|sFilters|']';
  i = 0; WHILE( i < nTargetDimensionCount ); i = i + 1;
    sDimension = TABDIM( sTargetCube, i );
    
    sTempFiltersList = '[]';
    nFiltersSize = JsonSize( sFiltersList ); WHILE( nFiltersSize > 0 ); nFiltersSize = nFiltersSize - 1;
      sTempFilters = JsonGet( sFiltersList, nFiltersSize );
      
      nDimMapSize = JsonSize( sTempFilters, '/pDimMap/'|sDimension ); WHILE( nDimMapSize > 0 ); nDimMapSize = nDimMapSize - 1;
        sTempFiltersList = JsonAdd( sTempFiltersList, '', JsonMove( sTempFilters, '/pDimMap/'|sDimension|'/'|NumberToString( nDimMapSize ), '/pDimMap/'|sDimension ) );
      END;
    END;
    IF( sTempFiltersList @<> '[]' );
      sFiltersList = sTempFiltersList;
    ENDIF;
  END;
  
  # Multi-Thread: For each set of parameters, loop through dimension, and each element in the dimension that is included in pFilter, but excluded in pExcept.
  nMultiThreadDimensionCount = JsonSize( pMultiThreadDimensions );
  IF( nMultiThreadDimensionCount > 0 );
    sTempFiltersList = '[]';
    i = 0;
    WHILE( i < nMultiThreadDimensionCount );
      sDimension = JsonToString( JsonGet( pMultiThreadDimensions, i ) );
  
      nSize = JsonSize( sFiltersList );
      WHILE( nSize > 0 );
        nSize = nSize - 1;
        sFilters = JsonGet( sFiltersList, nSize );
        ExecuteProcess('}bedrock.hier.sub.create.from_json',
          'pDimension', sDimension,
          'pSubset', cTemp,
          'pFilter', JsonGet( sFilters, '/pFilter/'|sDimension ),
          'pExcept', JsonGet( sFilters, '/pExcept/'|sDimension ) 
        );
        sFilters = JsonRemove( sFilters, '/pExcept/'|sDimension );
        
        nSubsetSize = SubsetGetSize( sDimension, cTemp );
        WHILE( nSubsetSize > 0 );
          sElement = SubsetGetElementName( sDimension, cTemp, nSubsetSize );
          
          sFilters = JsonReplace( sFilters, '/pFilter/'|sDimension, StringToJson( sElement ) );
          sTempFiltersList = JsonAdd( sTempFiltersList, 0, sFilters );
          
          nSubsetSize = nSubsetSize - 1;
        END;
      END;
      i = i + 1;
    END;
    IF( sTempFiltersList @<> '[]' );
      sFiltersList = sTempFiltersList;
    ENDIF;
  ENDIF;
  
  nSize = JsonSize( sFiltersList );
  IF( nSize <> 1 );
    Datasourcetype = 'NULL';
    
    # Single-Thread Recursive Call
    IF( nMultiThreadDimensionCount <= 0 % pMaxThreads = 1 );
      WHILE( nSize > 0 );
        nSize = nSize - 1;
        sJson = JsonGet( sFiltersList, nSize );
        sJson = JsonMergePatch( pJson, sJson );
        
        ExecuteProcess( cThisProcName, 'pJson', sJson );
      END;
      
    # Multi-Thread Recursive Call (using '}bedrock.process.multithread')
    ELSE;
      sTaskList = '[]';
      WHILE( nSize > 0 );
        nSize = nSize - 1;
        sJson = JsonGet( sFiltersList, nSize );
        sJson = JsonMergePatch( pJson, sJson );
  
